{() => {
                    if (!currentProject) return;
                    setFeedback(null);
                    if (!navigator.clipboard?.writeText) {
                      setFeedback({
                        tone: "error",
                        message:
                          "无法访问剪贴板：请改用“导出为 JSON”保存项目文件。",
                      });
                      closeMenu();
                      return;
                    }
                    let json: string;
                    try {
                      json = projectService.exportProject(currentProject.id);
                    } catch (error) {
                      reportDiagnostic(
                        "error",
                        "workbench:project-share",
                        error,
                      );
                      setFeedback({
                        tone: "error",
                        message:
                          "分享失败：项目导出异常，请改用“导出为 JSON”重试。",
                      });
                      closeMenu();
                      return;
                    }
                    void navigator.clipboard
                      .writeText(json)
                      .then(() =>
                        setFeedback({
                          tone: "success",
                          message: "项目 JSON 已复制到剪贴板。",
                        }),
                      )
                      .catch((error: unknown) => {
                        reportDiagnostic(
                          "error",
                          "workbench:clipboard-write",
                          error,
                        );
                        setFeedback({
                          tone: "error",
                          message:
                            "复制失败：请检查剪贴板权限，或改用“导出为 JSON”。",
                        });
                      });
                    closeMenu();
                  }}

